import { Request, Response } from "express";
import { AdvanceOrderUseCase } from "../application/AdvanceOrderUseCase";
import { CancelOrderUseCase } from "../application/CancelOrderUseCase";
import { ListOrdersByStatusUseCase } from "../application/ListOrdersByStatusUseCase";
import { PlaceOrderUseCase } from "../application/PlaceOrderUseCase";
import { DomainError } from "../domain/DomainError";

export class OrderController {
  constructor(
    private readonly placeOrder: PlaceOrderUseCase,
    private readonly advanceOrder: AdvanceOrderUseCase,
    private readonly cancelOrder: CancelOrderUseCase,
    private readonly listOrders: ListOrdersByStatusUseCase,
  ) {}

  place = async (req: Request, res: Response): Promise<void> => {
    const body: unknown = req.body;
    if (typeof body !== "object" || body === null) {
      throw new DomainError("invalid", "Request body is required");
    }
    const { customerId, lines } = body as { customerId?: unknown; lines?: unknown };
    if (typeof customerId !== "string" || !Array.isArray(lines)) {
      throw new DomainError("invalid", "customerId and lines are required");
    }
    const order = await this.placeOrder.execute({
      customerId,
      lines: lines.map((l: { productId?: unknown; quantity?: unknown } | null) => ({
        productId: l?.productId as string,
        quantity: l?.quantity as number,
      })),
    });
    res.status(201).json(order);
  };

  advance = async (req: Request, res: Response): Promise<void> => {
    res.json(await this.advanceOrder.execute(String(req.params.id)));
  };

  cancel = async (req: Request, res: Response): Promise<void> => {
    res.json(await this.cancelOrder.execute(String(req.params.id)));
  };

  list = async (req: Request, res: Response): Promise<void> => {
    res.json(await this.listOrders.execute(req.query.state));
  };
}

